g=[[9]*26 for _ in range(11)]
pts={ (4,10),(4,22),(5,22),(6,11),(6,13),(6,14),(6,15),(6,16),(6,17),(6,20),(6,21),(8,10),(8,19),(8,22)}
for r,c in pts:g[r][c]=3
# Fill strict gaps between adjacent original 3s in every row and column, using 2.
out=[row[:] for row in g]
for r in range(11):
    cs=sorted(c for rr,c in pts if rr==r)
    for a,b in zip(cs,cs[1:]):
        for c in range(a+1,b):
            if out[r][c]==9:out[r][c]=2
for c in range(26):
    rs=sorted(r for r,cc in pts if cc==c)
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b):
            if out[r][c]==9:out[r][c]=2
print('{"action":"submit","grid":'+__import__('json').dumps(out,separators=(',',':'))+'}')
